import java.util.*;
import org.objectweb.asm.*;
import org.objectweb.asm.tree.*;
import org.objectweb.asm.tree.analysis.*;
import static org.objectweb.asm.Opcodes.*;

/** Independent typed inverse of original HP operands and only their positive-commit gates. */
final class VerifyPlayerDamage{
 static final String P="local/lito381/server/",C=P+"ClientSession",H=P+"CombatPlayerDamage";
 static void require(boolean b,String why){if(!b)throw new AssertionError("signed PC commit "+why);}
 static AbstractInsnNode single(SourceValue v){require(v.insns.size()==1,"single original operand");return v.insns.iterator().next();}
 static String actor(SourceValue v,Frame<SourceValue>[] f,Map<AbstractInsnNode,Integer> ix){var n=single(v);if(n instanceof VarInsnNode a&&a.getOpcode()==ALOAD)return "pc:"+a.var;require(n instanceof TypeInsnNode t&&t.getOpcode()==CHECKCAST&&t.desc.equals(C),"original typed map PC");var frame=f[ix.get(n)];var get=single(frame.getStack(frame.getStackSize()-1));require(get instanceof MethodInsnNode m&&m.owner.equals("java/util/Map$Entry")&&m.name.equals("getKey")&&m.desc.equals("()Ljava/lang/Object;"),"original map key getter");var entry=f[ix.get(get)];return "map:"+local(entry.getStack(entry.getStackSize()-1),ALOAD);}
 static int local(SourceValue v,int op){var n=single(v);require(n instanceof VarInsnNode a&&a.getOpcode()==op,"exact original local");return ((VarInsnNode)n).var;}
 static String scalar(SourceValue v,Frame<SourceValue>[] f,Map<AbstractInsnNode,Integer> ix){var n=single(v);if(n instanceof VarInsnNode a&&a.getOpcode()==ILOAD)return "damage:"+a.var;require(n instanceof MethodInsnNode m&&m.owner.equals("java/lang/Integer")&&m.name.equals("intValue")&&m.desc.equals("()I"),"original map integer value");var before=f[ix.get(n)];var cast=single(before.getStack(before.getStackSize()-1));require(cast instanceof TypeInsnNode t&&t.getOpcode()==CHECKCAST&&t.desc.equals("java/lang/Integer"),"native integer cast");var frame=f[ix.get(cast)];var get=single(frame.getStack(frame.getStackSize()-1));require(get instanceof MethodInsnNode m&&m.owner.equals("java/util/Map$Entry")&&m.name.equals("getValue"),"native entry value");var entry=f[ix.get(get)];return "entry:"+local(entry.getStack(entry.getStackSize()-1),ALOAD);}
 static AbstractInsnNode prior(AbstractInsnNode n){return VerifyCombatPreservation.prior(n);}static AbstractInsnNode next(AbstractInsnNode n){return VerifyCombatPreservation.following(n);}
 static MethodNode normalize(MethodNode original){var m=new MethodNode(original.access,original.name,original.desc,original.signature,original.exceptions.toArray(String[]::new));original.accept(m);if(!Arrays.stream(m.instructions.toArray()).anyMatch(n->n instanceof MethodInsnNode c&&c.owner.equals(H)))return m;m.maxStack+=64;Frame<SourceValue>[] frames;try{frames=new Analyzer<>(new SourceInterpreter()).analyze(C,m);}catch(AnalyzerException e){throw new AssertionError(e);}var nodes=m.instructions.toArray();var ix=new IdentityHashMap<AbstractInsnNode,Integer>();for(int i=0;i<nodes.length;i++)ix.put(nodes[i],i);int commits=0,gates=0,minds=0,dolls=0,wires=0;
  for(int at=0;at<nodes.length;at++)if(nodes[at] instanceof MethodInsnNode call&&call.owner.equals(H)&&Set.of("worldGate","dollGate").contains(call.name)){
   require(call.getOpcode()==INVOKESTATIC&&call.desc.equals("(IL"+C+";L"+C+";)I"),"guard helper identity");var branch=next(call);require(branch instanceof JumpInsnNode j&&j.getOpcode()==IFLE,"unchanged native positive-only branch");var f=frames[at];int base=f.getStackSize()-3;String pc=actor(f.getStack(base+1),frames,ix),damage=scalar(f.getStack(base),frames,ix);require(local(f.getStack(base+2),ALOAD)==0,"same original caster");
   if(call.name.equals("worldGate")){int found=0;for(int i=at+1;i<ix.get(((JumpInsnNode)branch).label);i++)if(nodes[i] instanceof MethodInsnNode h&&h.owner.equals(H)&&h.name.equals("world")){var input=frames[i];int start=input.getStackSize()-4;require(actor(input.getStack(start),frames,ix).equals(pc)&&scalar(input.getStack(start+1),frames,ix).equals(damage),"same PC/damage through original guard and HP commit");found++;}require(found==1,"guard dominates exactly one original PC HP commit");gates++;}
   else{require(m.name.equals("applyNativeMagicDollAttackProcs")&&pc.equals("pc:4")&&damage.startsWith("damage:"),"native doll actual PC argument");int slot=Integer.parseInt(damage.substring(7));boolean found=false;for(int i=0;i<at;i++)if(nodes[i] instanceof MethodInsnNode p&&p.owner.equals(C)&&p.name.equals("nativeMagicDollTriggeredSkillDamage")){var store=next(p);found=store instanceof VarInsnNode s&&s.getOpcode()==ISTORE&&s.var==slot;}require(found,"doll guard is the actual source skill scalar");dolls++;}
   var caster=prior(call);var receiver=prior(caster);require(caster instanceof VarInsnNode a&&a.getOpcode()==ALOAD&&a.var==0,"guard caster load");m.instructions.remove(caster);
   if(receiver instanceof TypeInsnNode t&&t.getOpcode()==CHECKCAST){var get=prior(receiver);var entry=prior(get);require(get instanceof MethodInsnNode g&&g.owner.equals("java/util/Map$Entry")&&g.name.equals("getKey")&&entry instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&pc.equals("map:"+v.var),"pure existing target map producer");m.instructions.remove(entry);m.instructions.remove(get);}else require(receiver instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&pc.equals("pc:"+v.var),"pure existing target local producer");m.instructions.remove(receiver);m.instructions.remove(call);
  }
  for(var n:m.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(H)){
   if(call.name.equals("shockWire")){require(Set.of("useShockStunSpell","useClassicWorldShockStunSpell").contains(m.name)&&call.getOpcode()==INVOKESTATIC&&call.desc.equals("(IJJII)[B"),"only original Shock physical display damage");var f=frames[ix.get(call)];String value=scalar(f.getStack(f.getStackSize()-2),frames,ix);int matching=0;for(int j=ix.get(call)+1;j<nodes.length;j++)if(nodes[j] instanceof MethodInsnNode hp&&hp.owner.equals(H)&&Set.of("battle","world").contains(hp.name)){var frame=frames[j];int base=frame.getStackSize()-Type.getArgumentTypes(hp.desc).length;require(scalar(frame.getStack(base+1),frames,ix).equals(value),"Shock display adapter does not replace the actual signed HP scalar");matching++;}require(matching==1,"one subsequent native Shock HP commit");m.instructions.set(call,new MethodInsnNode(INVOKESTATIC,P+"Protocol","shockStunAttack",call.desc,false));wires++;}
   else   if(call.name.equals("mindMultiplier")){require(Set.of("useAttackSpell","useClassicWorldAttackSpell").contains(m.name)&&call.getOpcode()==INVOKESTATIC&&call.desc.equals("(L"+P+"BattleSpellCatalog$MindBreakSpell;I)I"),"native Mind Break mode receiver");m.instructions.set(call,new MethodInsnNode(INVOKEVIRTUAL,P+"BattleSpellCatalog$MindBreakSpell","damageAfterMultiplier","(I)I",false));minds++;}
   else{boolean world=call.name.equals("world"),terminal=call.name.equals("battleTerminal");String descriptor=world?"(IL"+C+";Z)V":terminal?"(IL"+C+";ZZJ)V":"(IL"+C+";)V";require((world||terminal||call.name.equals("battle"))&&call.getOpcode()==INVOKESTATIC&&call.desc.equals("(L"+C+";"+descriptor.substring(1)),"exact native HP overload and argument order");var input=frames[ix.get(call)];int start=input.getStackSize()-Type.getArgumentTypes(call.desc).length;actor(input.getStack(start),frames,ix);require(local(input.getStack(start+2),ALOAD)==0,"original HP caster operand");m.instructions.set(call,new MethodInsnNode(INVOKEVIRTUAL,C,world?"takeClassicWorldPlayerDamage":"takePlayerDamage",descriptor,false));commits++;}
  }
  if(m.name.equals("applyNativeMagicDollAttackProcs"))require(dolls==1&&commits==0&&gates==0&&minds==0&&wires==0,"one conditional PC doll gate only");else{Set<String> names=Set.of("useAreaAttackSpell","useAttackSpell","useCenteredAreaAttackSpell","useCenteredFreezeAttackSpell","useClassicWorldAreaAttackSpell","useClassicWorldAttackSpell","useClassicWorldCenteredAreaAttackSpell","useClassicWorldCenteredFreezeAttackSpell","useClassicWorldCounterDetectionSpell","useClassicWorldFreezeAttackSpell","useClassicWorldLineAttackSpell","useClassicWorldLineFreezeAttackSpell","useClassicWorldShockStunSpell","useCounterDetectionSpell","useFreezeAttackSpell","useLineAttackSpell","useShockStunSpell");require(names.contains(m.name)&&commits==1&&dolls==0&&gates==(m.name.startsWith("useClassicWorld")&&!m.name.equals("useClassicWorldCounterDetectionSpell")?1:0)&&wires==(Set.of("useShockStunSpell","useClassicWorldShockStunSpell").contains(m.name)?1:0)&&minds==(Set.of("useAttackSpell","useClassicWorldAttackSpell").contains(m.name)?2:0),"exact per-method HP/guard/mode counts="+m.name);}return m;
 }
}
